fn is_palindrome(text: Vec<char>) -> bool {
    fn to_ascii_lower(c: char) -> char {
        if ('A'..='Z').contains(&c) {
            // Safe because 'A'..='Z' are contiguous in ASCII.
            ((c as u32) + ('a' as u32 - 'A' as u32))
                .try_into()
                .unwrap()
        } else {
            c
        }
    }

    let n = text.len();
    for i in 0..(n / 2) {
        let left = to_ascii_lower(text[i]);
        let right = to_ascii_lower(text[n - 1 - i]);
        if left != right {
            return false;
        }
    }
    true
}